1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Pim\Filament\Schemas;
6	
7	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
8	use AtrioTeam\DigitalHub\Pim\Concerns\HasTechnicalAttributes;
9	use AtrioTeam\DigitalHub\Pim\Enum\Type;
10	use AtrioTeam\DigitalHub\Pim\TypeBuilder;
11	use Filament\Forms\Components\DatePicker;
12	use Filament\Forms\Components\Select;
13	use Filament\Forms\Components\Textarea;
14	use Filament\Forms\Components\TextInput;
15	use Filament\Forms\Components\Toggle;
16	use Filament\Schemas\Components\Component;
17	use Filament\Schemas\Components\Group;
18	use Filament\Schemas\Components\Tabs;
19	use Filament\Schemas\Components\Tabs\Tab;
20	use Filament\Schemas\Components\Utilities\Get;
21	use Filament\Schemas\Schema;
22	use Illuminate\Database\Eloquent\Model;
23	
24	/**
25	 * Generatore Filament form da uno schema di attributi PIM.
26	 *
27	 * Uso tipico in una Resource:
28	 *   return $schema->components([
29	 *       TextInput::make('name'),
30	 *       AttributesEditor::for($schema),
31	 *   ]);
32	 *
33	 * Genera una Tabs con un tab per ogni gruppo dichiarato dallo schema; ogni
34	 * tab contiene gli input giusti per ciascun attributo (text/numeric/
35	 * select/toggle/date) con label, required, min/max, unit risolti dallo
36	 * schema stesso.
37	 */
38	class AttributesEditor
39	{
40	    /**
41	     * Costruisce le tab degli attributi dal Filament Schema del form.
42	     *
43	     */
44	    public static function for(Schema $schema): Tabs
45	    {
46	        $instance = self::resolveInstance($schema);
47	
48	        /** @var AttributeSchema|null $attributeSchema */
49	        // @phpstan-ignore method.notFound (HasTechnicalAttributes trait, asserted in resolveInstance)
50	        $attributeSchema = $instance->attributeSchema();
51	
52	        return self::buildTabs($instance, $attributeSchema);
53	    }
54	
55	    /**
56	     * Variante reattiva: avvolge le Tabs in un container che si rigenera quando
57	     * cambia lo stato del form. Lo schema attributi da usare viene risolto a ogni
58	     * render dalla closure $schemaResolver, che riceve il Get del form.
59	     *
60	     * Perché serve: for() risolve lo schema una volta sola alla prima render. Su
61	     * un modello che risolve dinamicamente lo schema (es. Product → ProductType),
62	     * cambiare la tipologia nel form non aggiornerebbe i campi. Il container Group
63	     * con schema() a closure ri-esegue il resolver a ogni cambio reattivo.
64	     *
65	     * Il core resta agnostico su come si risolve lo schema: è il template a
66	     * fornire $schemaResolver (es. leggendo product_type_id da $get e mappandolo
67	     * sulla AttributeSchema della tipologia).
68	     *
69	     * @param \Closure(Get): ?AttributeSchema $schemaResolver
70	     */
71	    public static function reactive(Schema $schema, \Closure $schemaResolver): Group
72	    {
73	        $instance = self::resolveInstance($schema);
74	
75	        return Group::make()->schema(function (Get $get) use ($instance, $schemaResolver): array {
76	            return [self::buildTabs($instance, $schemaResolver($get))];
77	        });
78	    }
79	
80	    /**
81	     * Risolve l'istanza del modello dal Filament Schema e ne verifica il trait.
82	     *
83	     * In update abbiamo l'istanza del record ($schema->getRecord()); in create
84	     * solo la class-string del modello ($schema->getModel()), da cui istanziamo.
85	     * La risoluzione dello schema attributi può dipendere dai dati del record
86	     * (es. Product risolve dallo schema della ProductType associata): una nuova
87	     * istanza vuota non li risolverebbe correttamente.
88	     */
89	    private static function resolveInstance(Schema $schema): Model
90	    {
91	        $recordOrClassName = $schema->getRecord() ?? $schema->getModel();
92	
93	        // if a concrete istance is not passed, create one.
94	        /** @var Model $instance */
95	        $instance = is_string($recordOrClassName) ? new $recordOrClassName() : $recordOrClassName;
96	
97	        // model must use HasTechnicalAttributes!
98	        if (! in_array(HasTechnicalAttributes::class, class_uses_recursive($instance), true)) {
99	            throw new \InvalidArgumentException(
100	                'Model [' . get_class($instance) . '] must use the HasTechnicalAttributes trait.',
101	            );
102	        }
103	
104	        return $instance;
105	    }
106	
107	    /**
108	     * Costruisce la Tabs degli attributi da uno schema esplicito. Lo schema è
109	     * passato esplicitamente (non riletto da $instance) così la variante reattiva
110	     * può fornire uno schema diverso da quello attualmente risolto sul record.
111	     * Se lo schema è null (nessun attributo), le Tabs vengono nascoste.
112	     *
113	     * @param Model $instance model using the HasTechnicalAttributes trait
114	     */
115	    private static function buildTabs(Model $instance, ?AttributeSchema $attributeSchema): Tabs
116	    {
117	        /** @var string $column */
118	        // @phpstan-ignore method.notFound (HasTechnicalAttributes trait)
119	        $column = $instance->attributesColumn();
120	
121	        // lopp thorugh schema groups and attributes to build tabs and fields
122	        $tabs = [];
123	        $totalFieldsCount = 0;
124	        if ($attributeSchema !== null) {
125	            // regole di validazione per ogni attributo (incl. unique sul path JSON,
126	            // con ignore del record in update): risolte dal modello concreto.
127	            $validationRules = $attributeSchema->validationRules($instance);
128	
129	            foreach ($attributeSchema->groups() as $groupKey => $attrKeys) {
130	                $fields = [];
131	                foreach ($attrKeys as $key) {
132	                    $type = $attributeSchema->getType($key);
133	                    if ($type !== null) {
134	                        $fields[] = self::buildField($column, $key, $type, $instance, $validationRules[$key] ?? []);
135	                        $totalFieldsCount++;
136	                    }
137	                }
138	                /** @var string $groupLabel */
139	                // @phpstan-ignore method.notFound (HasTechnicalAttributes trait)
140	                $groupLabel = $instance->attrGroupLabel((string) $groupKey);
141	                $tabs[] = Tab::make($groupLabel)->schema($fields);
142	            }
143	        }
144	
145	
146	        $tabs = Tabs::make()->tabs($tabs);
147	
148	        if ($totalFieldsCount === 0) {
149	            $tabs->hidden();
150	        }
151	
152	        return $tabs;
153	    }
154	
155	    /**
156	     * Model è atteso usare il trait HasTechnicalAttributes (controllato in for()).
157	     *
158	     * @param Model $instance model using the HasTechnicalAttributes trait
159	     * @param list<mixed> $validationRules regole Laravel per questo attributo (da AttributeSchema::validationRules)
160	     */
161	    private static function buildField(string $column, string $key, TypeBuilder $type, Model $instance, array $validationRules): Component
162	    {
163	        $name = "{$column}.{$key}";
164	        /** @var string $label */
165	        // @phpstan-ignore method.notFound (HasTechnicalAttributes trait)
166	        $label = $instance->attrLabel($key);
167	
168	        $field = match ($type->kind()) {
169	            Type::String => TextInput::make($name),
170	            Type::Text => Textarea::make($name)->rows(4),
171	            Type::Int => TextInput::make($name)->numeric()->integer(),
172	            Type::Decimal => TextInput::make($name)->numeric(),
173	            Type::Bool => Toggle::make($name),
174	            Type::Date => DatePicker::make($name),
175	            Type::Enum => Select::make($name)->options(
176	                array_combine(
177	                    $type->getOptions(),
178	                    array_map(
179	                        static function (string $opt) use ($instance, $key): string {
180	                            /** @var string $label */
181	                            // @phpstan-ignore method.notFound (HasTechnicalAttributes trait, returns string)
182	                            $label = $instance->attrOption($key, $opt);
183	
184	                            return $label;
185	                        },
186	                        $type->getOptions(),
187	                    ),
188	                ),
189	            ),
190	        };
191	
192	        $field->label($label);
193	
194	        if ($type->isRequired()) {
195	            $field->required();
196	        }
197	
198	        if ($type->getMin() !== null && method_exists($field, 'minValue')) {
199	            $field->minValue($type->getMin());
200	        }
201	
202	        if ($type->getMax() !== null && method_exists($field, 'maxValue')) {
203	            $field->maxValue($type->getMax());
204	        }
205	
206	        if ($type->getUnit() !== null && method_exists($field, 'suffix')) {
207	            $field->suffix($type->getUnit());
208	        }
209	
210	        // Regole non già mappate sui metodi nativi del field (required/min/max sopra):
211	        // in particolare unique, che opera sul path JSON e va imposta come regola Laravel.
212	        // Le stringhe scalari di base sono già coperte dai metodi nativi: si escludono per
213	        // non duplicarle.
214	        $extraRules = array_values(array_filter(
215	            $validationRules,
216	            static fn (mixed $rule): bool => ! is_string($rule)
217	                || ! preg_match('/^(required|nullable|string|integer|numeric|boolean|date|min:|max:|regex:)/', $rule),
218	        ));
219	
220	        if ($extraRules !== []) {
221	            $field->rules($extraRules);
222	        }
223	
224	        // Attributi translatable (solo String/Text): il valore è salvato come map
225	        // {locale: value} nello stesso JSON. Il campo viene avvolto in una
226	        // TranslationSection che lo clona per ogni locale gestita, spostando lo
227	        // statePath da {column}.{key} a {column}.{key}.{locale}. Stesso pattern del
228	        // `name` (NameAndId). Le regole native già applicate sopra (required/min/max)
229	        // vengono clonate su ogni tab, quindi valgono per-locale.
230	        if ($type->isTranslatable() && in_array($type->kind(), [Type::String, Type::Text], true)) {
231	            /** @var array<string, string> $locales */
232	            $locales = (array) config('digital-hub.locales');
233	
234	            return TranslationSection::make()
235	                ->locales($locales)
236	                ->schema([$field]);
237	        }
238	
239	        return $field;
240	    }
241	}
