33	/**
34	 * A simple Filament plugin to configure the panel via this package.
35	 */
36	class DigitalHubPlugin implements Plugin
37	{
38	    public static function make(): static
39	    {
40	        /** @var static $plugin */
41	        $plugin = app(static::class);
42	
43	        return $plugin;
44	    }
45	
46	    public function getId(): string
47	    {
48	        return 'digital-hub';
49	    }
