51	    public function register(Panel $panel): void
52	    {
53	        // Pagine di autenticazione con layout "simple" a cui applicare lo
54	        // sfondo custom: login e recupero password (richiesta link + reset).
55	        $authPages = [
56	            Login::class,
57	            RequestPasswordReset::class,
58	            ResetPassword::class,
59	        ];
60	
61	        $panel
62	            ->plugin(MinimalTheme::make())
63	            ->viteTheme('vendor/atrioteam/digital-hub/resources/theme/digital-hub-theme.css')
64	            ->font('Open Sans')
65	            ->pages([
66	                Catalog::class,
67	                AssetManager::class,
68	                ManageGeneralSettings::class,
69	            ])
