71	            // nascoste dalla nav (parent registration): in sidebar solo i gruppi.
72	            // Due alberi paralleli scopati per target: anagrafiche e asset.
73	            ->resources([
74	                TagGroupResource::class,
75	                TagCategoryResource::class,
76	                TagResource::class,
77	                AssetTagGroupResource::class,
78	                AssetTagCategoryResource::class,
