227	    /**
228	     * Risolve la palette colori (shade 50..950) da usare come primary del panel.
229	     * Ordine: setting general.primary_color (modalità "palette" = nome costante
230	     * Filament, "custom" = hex libero da cui generare la palette), poi fallback
231	     * sul config. Se la lettura delle settings fallisce (DB/tabella non
232	     * disponibile in console o durante le migration) si ricade sul config senza
233	     * sollevare eccezioni. Ritorna null se non c'è alcun colore configurato.
234	     *
235	     * @return array<int, string>|null
236	     */
237	    private static function resolvePrimaryPalette(): ?array
238	    {
239	        try {
240	            $settings = app(GeneralSettings::class);
241	
242	            if ($settings->primary_color_mode === 'custom') {
243	                if (filled($settings->primary_color_custom)) {
244	                    return \Filament\Support\Colors\Color::hex($settings->primary_color_custom);
245	                }
246	            } elseif (filled($settings->primary_color)) {
247	                return self::paletteFromName($settings->primary_color);
248	            }
249	        } catch (\Throwable) {
250	            // settings non disponibili: si usa il config
251	        }
252	
253	        $fromConfig = config('digital-hub.primary_color');
254	
255	        return is_string($fromConfig) && $fromConfig !== ''
256	            ? self::paletteFromName($fromConfig)
257	            : null;
258	    }
