260	    /**
261	     * Restituisce la palette di una costante colore di Filament dato il suo nome
262	     * (es. "Amber"), o null se il nome non corrisponde ad alcuna costante.
263	     *
264	     * @return array<int, string>|null
265	     */
266	    private static function paletteFromName(string $name): ?array
267	    {
268	        if (! defined(\Filament\Support\Colors\Color::class . '::' . $name)) {
269	            return null;
270	        }
271	
272	        /** @var array<int, string> $palette */
273	        $palette = \Filament\Support\Colors\Color::{$name};
274	
275	        return $palette;
276	    }
