280	     * button primari (pieni). Agisce solo su `.fi-color-primary` non-outlined,
281	     * impostando le variabili CSS del testo di Filament (--text e relativi stati
282	     * hover/dark) con `!important` per battere gli stili inline del componente.
283	     * Lo sfondo dei button resta invariato.
284	     */
285	    private static function buttonTextColorStyle(string $hex): string
286	    {
287	        $text = e($hex);
288	
289	        return '<style>
290	            .fi-btn.fi-color-primary:not(.fi-outlined):not(label) {
291	                --text: ' . $text . ' !important;
292	                --hover-text: ' . $text . ' !important;
293	                --dark-text: ' . $text . ' !important;
294	                --dark-hover-text: ' . $text . ' !important;
295	            }
296	        </style>';
297	    }
