299	    /**
300	     * Genera il blocco <style> che sovrascrive il colore di sfondo dell'area
301	     * contenuto (la parte destra della pagina). Agisce su `.fi-body` con
302	     * `!important`, così vale sia in light che in dark mode; la sidebar, opaca,
303	     * copre la sua porzione a sinistra.
304	     */
305	    private static function contentBackgroundStyle(string $hex): string
306	    {
307	        $color = e($hex);
308	
309	        return '<style>
310	            .fi-body {
311	                background-color: ' . $color . ' !important;
312	            }
313	        </style>';
314	    }
