316	    /**
317	     * Costruisce una stringa CSS `rgba(...)` per l'overlay della login a partire
318	     * dal colore esadecimale (#rgb o #rrggbb) e dall'opacità (0..1) salvati nelle
319	     * impostazioni. Input non validi degradano a nero/opacità clampata.
320	     */
321	    private static function overlayRgba(string $hex, float $opacity): string
322	    {
323	        $hex = ltrim($hex, '#');
324	
325	        if (strlen($hex) === 3) {
326	            $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
327	        }
328	
329	        if (! ctype_xdigit($hex) || strlen($hex) !== 6) {
330	            $hex = '000000';
331	        }
332	
333	        $r = (int) hexdec(substr($hex, 0, 2));
334	        $g = (int) hexdec(substr($hex, 2, 2));
335	        $b = (int) hexdec(substr($hex, 4, 2));
336	        $alpha = max(0.0, min(1.0, $opacity));
337	
338	        return sprintf('rgba(%d, %d, %d, %s)', $r, $g, $b, rtrim(rtrim(number_format($alpha, 2, '.', ''), '0'), '.'));
339	    }
